insert into public.pattern_library (slug, name, description, replacement, if_then, two_minute_start, sort_order) values
('procrastination', 'Procrastination', 'Putting off the thing that matters, usually for something easier.', 'Start for two minutes.', 'If I notice I am putting it off, then I start the smallest piece for two minutes.', 'Open the document, file or app and do the first physical step.', 1),
('not_finishing', 'Not finishing', 'Starting well and letting things trail off before they are done.', 'Define the next physical action and do only that.', 'If I feel the pull to move on before it is finished, then I write the definition of done and do the next action.', 'Write one line: what does finished look like?', 2),
('starting_too_much', 'Starting too many things', 'Adding new initiatives before current ones are finished.', 'Put it in the Idea Parking Lot.', 'If I have a new idea, then I park it instead of starting it.', 'Open the Parking Lot and write one line.', 3),
('chasing_misaligned', 'Chasing silver bullets', 'Pursuing opportunities that do not serve the five-year vision.', 'Ask: what current priority would this replace?', 'If something shiny appears, then I run it through the six filter questions before touching it.', 'Write the opportunity in one sentence and park it.', 4),
('hiding', 'Hiding when I should be visible', 'Staying quiet, unpublished or in the background when the work needs me seen.', 'Perform one small visible action.', 'If I want to postpone publishing, then I publish the smallest viable version.', 'Turn the camera on and record the opening line.', 5),
('overthinking', 'Overthinking instead of acting', 'Analysing, planning and reconsidering in place of doing.', 'Define the next physical action and do it.', 'If I have been thinking about it for ten minutes, then I do the next physical action.', 'Write the next action in six words and do it.', 6),
('avoiding_conversations', 'Avoiding difficult conversations', 'Letting an important conversation wait because it is uncomfortable.', 'Schedule or start it within 24 hours.', 'If I am avoiding a conversation, then I send the first sentence today.', 'Write the first sentence.', 7),
('approval_seeking', 'Seeking approval', 'Shaping decisions around what others will think.', 'Ask: what do I believe is the right decision?', 'If I notice approval-seeking, then I ask what I would decide if nobody else knew.', 'Write your own answer first, before asking anyone.', 8),
('fear_of_risk', 'Avoiding calculated risk', 'Letting fear decide instead of judgement.', 'Review the evidence and take one concrete step.', 'If fear is the only reason not to act, then I take the smallest real step.', 'List the worst realistic outcome in one line.', 9),
('relationship_drift', 'Letting relationships drift', 'Allowing time to pass without contact with the people who matter.', 'Send the message or make the call.', 'If a relationship is drifting, then I make contact today.', 'Send a short message now.', 10),
('work_over_health', 'Putting work ahead of health', 'Skipping training, sleep or meals for work.', 'Train first, then work.', 'If I am about to skip training for work, then I do the shortest version of the session instead.', 'Put training clothes on.', 11),
('financial_anxiety', 'Letting money worry drive behaviour', 'Making decisions from scarcity rather than strategy.', 'Return to the plan and the next action.', 'If I notice financial anxiety, then I review the numbers and act on one thing within my control.', 'Write the one action that moves income this week.', 12),
('self_doubt', 'Acting from self-doubt', 'Shrinking decisions and ambitions to fit a smaller self-image.', 'Review the evidence and take one concrete action.', 'If I hear self-doubt, then I list three pieces of evidence and act once.', 'Write three things you have already done.', 13),
('comparison', 'Comparing myself with others', 'Measuring progress against other people instead of my own trajectory.', 'Return attention to my own trajectory.', 'If I catch myself comparing, then I open Progress and look at my own line.', 'Open Progress.', 14),
('worrying_what_people_think', 'Worrying what people think', 'Spending energy on imagined judgement.', 'Ask: what would my Prime Self do here?', 'If I am worrying what people think, then I act on what I believe is right.', 'Write the decision you would make if nobody was watching.', 15);
