insert into public.content_snippets (key, body) values
('score_line_90', 'A Prime Self day.'),
('score_line_70', 'Solid. The man is being built.'),
('score_line_50', 'Mixed day. Return tomorrow.'),
('score_line_0', 'A reset day. One miss is an event. Return tomorrow.'),
('miss_line', 'One miss is an event. Two can become a pattern. Return today.'),
('courage_line', 'Courage Rep recorded. A vote for your Prime Self.'),
('pattern_logged_line', 'Logged. One appearance is information, not a verdict.'),
('vision_quote', 'I didn''t waste it. I became the man I knew I could become.'),
('vision_question', 'Is today''s behaviour worthy of that future?'),
('identity_example_1', 'I am a man who shares his ideas even when it is uncomfortable.'),
('identity_example_2', 'I am someone for whom physical excellence is normal.'),
('identity_example_3', 'I am a father who deliberately invests in his relationships.'),
('identity_example_4', 'I am someone who finishes what he starts.'),
('example_health', 'At 66 I weigh 77 kg at around 11% body fat, year-round. I look mid-forties and move like someone twenty years younger. Training is simply what I do; not training would feel strange. I sleep well, eat with discipline, walk the beach most mornings, and can say without irony that I am in the top 1% physically for my age.'),
('example_purpose', 'I am the recognised front person for a brand that has helped thousands of men reclaim the second half of their lives. A small team and a CEO run the day to day. My work is content, mentoring, speaking, retreats and strategy. Income comes from several machines I built, not from my hours. Money means choice, freedom and the ability to support the people I love.'),
('example_relationships', 'Christine and I are best friends and partners, with deliberate time together, travel, intimacy and peace. My children call because they want to, visit both ways, and are proud of their father. I am present for my family, generous with my friends, and some of the men I mentor have become genuine friends.'),
('example_lifestyle', 'A three-bedroom penthouse on the Gold Coast with the ocean in front of me, and a small place near the Amalfi Coast. Three or four international trips a year, often a month at a time. Fine dining a couple of nights a week. A premium health and longevity club. Golf. A wardrobe that looks like a stylish man in his forties. Luxury as freedom, quality and time, never as display.'),
('example_moment', 'I am sitting on the Amalfi Coast with an espresso, looking across the Mediterranean at the fishing boats. There is stillness. Christine loves and trusts me. My children are proud of me. Thousands of men are better off because of my work. I built financial independence and extraordinary health, repaired what needed repairing, and stopped wasting my potential. I didn''t waste it. I became the man I knew I could become.'),
('stuck_why_fear', 'Fear'),
('stuck_why_uncertainty', 'Uncertainty'),
('stuck_why_complexity', 'Complexity'),
('stuck_why_boredom', 'Boredom'),
('stuck_why_perfectionism', 'Perfectionism'),
('stuck_why_rejection', 'Rejection'),
('stuck_why_difficult_conversation', 'A difficult conversation'),
('stuck_why_dont_know_where_to_begin', 'I don''t know where to begin'),
('stuck_why_other', 'Something else');
